s.do@vibetemp.in", "name": "Rtr. Janani BS", "phone": "", "dob": "", "club": "Chennai Capital", "access_role": "district_official", "club_position": "member", "designation": "Creative content head"}]$j$;
  m JSONB; uid UUID; cid UUID; em TEXT; made INT := 0; upd INT := 0;
BEGIN
  FOR m IN SELECT * FROM jsonb_array_elements(ppl) LOOP
    em := lower(trim(m->>'email'));
    SELECT id INTO uid FROM auth.users WHERE lower(email) = em;
    IF uid IS NULL THEN
      uid := gen_random_uuid();
      INSERT INTO auth.users (id, aud, role, email, encrypted_password,
        email_confirmed_at, created_at, updated_at, raw_user_meta_data, raw_app_meta_data,
        is_super_admin, instance_id)
      VALUES (uid,'authenticated','authenticated', em, crypt('Rotaract@3233', gen_salt('bf')),
        now(), now(), now(), jsonb_build_object('full_name', m->>'name'), '{}'::jsonb, false,
        '00000000-0000-0000-0000-000000000000');
      made := made + 1;
    ELSE upd := upd + 1;
    END IF;
    SELECT id INTO cid FROM public.clubs WHERE lower(name) = lower(m->>'club');
    UPDATE public.profiles SET
      full_name = m->>'name',
      designation = NULLIF(m->>'designation',''),
      phone_number = NULLIF(m->>'phone',''),
      date_of_birth = NULLIF(m->>'dob','')::date,
      access_role = m->>'access_role',
      club_position = m->>'club_position',
      club_id = cid,
      membership_status = 'active'
    WHERE id = uid;
    IF NOT FOUND THEN
      INSERT INTO public.profiles (id, email, full_name, role, designation, phone_number, date_of_birth, access_role, club_position, club_id, membership_status)
      VALUES (uid, em, m->>'name','member', NULLIF(m->>'designation',''), NULLIF(m->>'phone',''), NULLIF(m->>'dob','')::date, m->>'access_role', m->>'club_position', cid, 'active');
    END IF;
  END LOOP;
  RAISE NOTICE 'seed done — created %, updated %', made, upd;
END $$;

COMMIT;

-- 3) Verify
SELECT
  (SELECT count(*) FROM auth.users)                              AS auth_users,
  (SELECT count(*) FROM public.profiles)                         AS profiles,
  (SELECT count(*) FROM public.clubs)                            AS clubs,
  (SELECT count(*) FROM public.profiles WHERE club_id IS NULL)   AS profiles_no_club;
SELECT access_role, count(*) FROM public.profiles GROUP BY access_role ORDER BY count(*) DESC;